'use strict';
let content=[],lessons={},sources=[],subskills=[],units=[],curriculum=[];
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const info={数通:['数据通信','交换、路由与网络互联'],DCN:['数据中心 DCN','数据中心架构、云平台与算力网络'],安全:['网络安全','安全机制、防护技术与安全方案'],WLAN:['无线 WLAN','无线接入、组网、规划与运维']};
let filters={group:'全部',stage:'全部',depth:'全部',query:''};
function toast(t){$('.toast').textContent=t;$('.toast').classList.add('show');setTimeout(()=>$('.toast').classList.remove('show'),2200)}
function safeURL(url){try{let u=new URL(url);return ['http:','https:'].includes(u.protocol)?esc(u.href):'#'}catch{return '#'}}
function paragraphs(t){return String(t||'').split(/\n+/).filter(Boolean).map(p=>`<p>${esc(p)}</p>`).join('')}
function badges(x){return `${x.hcia?'<span class="badge">省资格赛</span>':''}${x.hcip?'<span class="badge blue">省赛</span>':''}${!x.hcia&&!x.hcip?'<span class="badge gray">原考纲未勾选</span>':''}`}
function heading(title,sub){return `<div class="page-heading"><div><div class="eyebrow">ICT KNOWLEDGE GUIDE</div><h1>${esc(title)}</h1><p class="sub">${esc(sub)}</p></div></div>`}
function depth(t){return t==='原理/配置（原文未标级）'?'原理与配置':t}
function searchable(x){return [x.id,x.title,x.category,x.detail,x.explanation,...Object.values(lessons[x.title]||{}),...subskills.filter(s=>s.parent===x.id).map(s=>s.term),...units.filter(u=>u.parent===x.id).map(u=>[u.term,u.explain,JSON.stringify(u.walkthrough||{}),u.config?.code||''].join(' '))].join(' ').toLowerCase()}
function mapPage(group){if(group)filters.group=Object.hasOwn(info,group)?group:'全部';return heading('考纲知识目录','按考纲阅读概念、原理、工作机制与配置，建立完整的网络知识体系。')+`<div class="track-grid">${Object.entries(info).map(([g,[t,d]])=>`<a class="track-card" href="#/map/${g}"><h2>${t}</h2><p>${d}</p><div class="meta">${content.filter(x=>x.group===g).length} 个考纲条目 →</div></a>`).join('')}</div><div class="tabs" id="group-tabs">${['全部',...Object.keys(info)].map(g=>`<button data-group="${g}" class="${filters.group===g?'active':''}">${g==='全部'?'全部方向':info[g][0]}</button>`).join('')}</div><div class="filterbar"><input id="map-query" aria-label="搜索知识点" type="search" placeholder="搜索知识点、协议或配置命令" value="${esc(filters.query)}"><select id="stage-filter" aria-label="比赛阶段"><option>全部</option><option>省资格赛</option><option>省赛</option><option>原图未勾选</option></select><select id="depth-filter" aria-label="考纲要求"><option>全部</option><option>了解</option><option>熟悉</option><option>掌握</option><option value="原理/配置（原文未标级）">原理与配置</option></select></div><div class="section-title"><h2>知识章节</h2><span class="page-count" id="result-count"></span></div><div id="knowledge-list" class="knowledge-list"></div>`}
function filtered(){return content.filter(x=>(filters.group==='全部'||x.group===filters.group)&&(filters.stage==='全部'||filters.stage==='省资格赛'&&x.hcia||filters.stage==='省赛'&&x.hcip||filters.stage==='原图未勾选'&&!x.hcia&&!x.hcip)&&(filters.depth==='全部'||x.depth===filters.depth)&&searchable(x).includes(filters.query.toLowerCase().trim()))}
function renderList(){let a=filtered();$('#result-count').textContent=`${a.length} / ${content.length} 个考纲条目`;$('#knowledge-list').innerHTML=a.length?a.map(x=>`<a class="knowledge" href="#/lesson/${x.id}"><span class="id">${x.id}</span><div><h3>${esc(x.title)}</h3><p>${esc(x.group)} / ${esc(x.category)} · ${esc(x.detail)}</p></div><div>${badges(x)}<span class="badge gray">${esc(depth(x.depth))}</span></div></a>`).join(''):'<p class="empty">没有匹配的知识点，请调整关键词或筛选条件。</p>'}
function flow(nodes){return `<div class="topology"><div class="flow">${nodes.map((n,i)=>`${i?'<span class="edge">→</span>':''}<div class="node">${esc(n[0])}<small>${esc(n[1])}</small></div>`).join('')}</div><p class="figcaption">原理示意 · 具体行为以协议条件和设备版本为准</p></div>`}
function stepsHTML(a){return `<ol class="process-list">${a.map((s,i)=>`<li><span>${i+1}</span><p>${esc(s)}</p></li>`).join('')}</ol>`}
function cleanExplanation(u,x){let t=u.explain;for(let suffix of [lessons[x.title]?.deep,x.explanation])if(suffix&&t.endsWith(suffix))t=t.slice(0,-suffix.length).trim();return t}
function referenceHTML(a){return a.map(s=>`<div class="source"><a href="${safeURL(s.url)}" target="_blank" rel="noopener">${esc(s.title)} ↗</a><p>${esc(s.version||'')}${s.accessed?' · 查阅 '+esc(s.accessed):''}</p></div>`).join('')}
function codeHTML(code,version){return `<pre><code>${esc(code)}</code></pre>${version?`<p class="lab-note">适用参考：${esc(version)}</p>`:''}`}
function walkthroughHTML(w){return w?`<div class="worked-example"><h3>跟着例子走：${esc(w.title)}</h3><p class="example-setup">${esc(w.setup)}</p>${stepsHTML(w.steps)}<p><strong>由此可见：</strong>${esc(w.conclusion)}</p></div>`:''}
function unitSection(u,x){return `<section class="knowledge-section" id="${u.id}"><h2>${esc(u.term)}</h2><p class="section-meta">考纲要求：${esc(depth(u.depth))}</p>${paragraphs(cleanExplanation(u,x))}${window.ICTTeaching?.forUnit(u.id)||''}${u.process?.length&&JSON.stringify(u.process)!==JSON.stringify(u.walkthrough?.steps)?`<h3>工作过程</h3>${stepsHTML(u.process)}`:''}${walkthroughHTML(u.walkthrough)}${u.config?.code?`<h3>配置与查询</h3>${codeHTML(u.config.code,u.config.platform)}${u.config.notes?`<p class="lab-note">${esc(u.config.notes)}</p>`:''}${u.commandNotes?.length?`<ul class="command-notes">${u.commandNotes.map(n=>`<li>${esc(n)}</li>`).join('')}</ul>`:''}`:''}${u.fault?`<h3>易混淆之处与故障原因</h3><p>${esc(u.fault.symptom)}：${esc(u.fault.cause)}。${esc(u.fault.check)}；${esc(u.fault.fix)}。</p>`:''}</section>`}
function orderedChapters(){return curriculum.flatMap(stage=>stage.chapters).map(id=>content.find(x=>x.id===id)).filter(Boolean)}
function learningPage(){let chapters=orderedChapters();return heading('从零开始，按顺序读懂网络','九个阶段串起全部94章。沿左侧目录或章节底部的下一章阅读；原考纲编号与范围完整保留。')+`<section class="start-guide"><h2>开始前：先认识一条通信路径</h2><p>终端是使用网络的电脑或手机。交换机连接同一个局域网里的设备；路由器连接不同的IP网段。网关是终端发往其他网段时交给的下一跳。无线AP让手机通过无线信号接入这张网络。</p><div class="plain-path">电脑A → 交换机 → 路由器 → 另一网络的服务器</div><p>MAC地址用于本链路的帧交付，IP地址帮助跨网络寻找目的地，端口号把收到的数据交给对应程序。“帧”是链路层传输单元，“IP包”是网际层传输单元；同一份上层数据会装入这些外层结构。</p><p>先理解数据为什么这样走，再看命令如何表达。章节中的例子会给出场景、逐步过程和结果，不需要先背完缩写。</p><a class="primary" href="#/lesson/${chapters[0]?.id}">从第一章开始 →</a></section>${curriculum.map((stage,i)=>`<section class="learning-stage" id="${stage.id}"><div class="section-title"><h2>${i+1}. ${esc(stage.title)}</h2><span class="page-count">${stage.chapters.length} 章</span></div><p class="sub">${esc(stage.description)}</p><ol class="learning-chapters">${stage.chapters.map(id=>{let x=content.find(x=>x.id===id);return `<li><a href="#/lesson/${id}"><strong>${esc(x.title)}</strong><span>${esc(x.outcome)}</span></a></li>`}).join('')}</ol></section>`).join('')}`}
function learningSidebar(id){let host=$('#learning-order');if(!host)return;let opened=new Set([...host.querySelectorAll('details[open]')].map(d=>d.dataset.stage));let active=curriculum.find(stage=>stage.chapters.includes(id));host.innerHTML=curriculum.map((stage,i)=>`<details data-stage="${stage.id}" ${opened.has(stage.id)||active?.id===stage.id||!id&&i===0?'open':''}><summary>${i+1}. ${esc(stage.title)}</summary><ol>${stage.chapters.map(cid=>{let x=content.find(x=>x.id===cid);return `<li><a href="#/lesson/${cid}" ${cid===id?'class="current" aria-current="page"':''}>${esc(x.title)}</a></li>`}).join('')}</ol></details>`).join('');if(id)host.querySelector('.current')?.scrollIntoView({block:'nearest'});else $('.sidebar').scrollTop=0}
const diagrams={'ICT-002':['subnet','IPv4地址与前缀'], 'ICT-004':['vlan','VLAN标签处理'],'ICT-009':['route','最长前缀与路由选择']};
function getSourceIDs(x){let t=x.title;if(lessons[t]?.sources)return lessons[t].sources;if(/OSPF/.test(t))return ['ospf','routing'];if(/BGP/.test(t))return ['bgp','routing'];if(/IPv6|SRv6/.test(t))return ['ipv6'];if(/EVPN/.test(t))return ['evpn','vxlan'];if(/VXLAN/.test(t))return ['vxlan','evpn'];if(/M-LAG/.test(t))return ['mlag','vxlan','evpn'];if(/OpenStack/.test(t))return ['openstack','k8s'];if(['交换技术','网络可靠性与网络优化技术'].includes(x.category))return ['switch'];if(x.category==='路由技术')return ['routing'];if(x.title==='TCP/IP协议基础'||x.title==='以太网交换基础')return ['arp','subnet'];if(x.group==='WLAN')return /漫游/.test(t)?['roaming']:['capwap','wlansecurity'];if(x.group==='安全')return /VPN/.test(t)?['ipsec']:['security'];if(x.group==='DCN')return ['mlag','vxlan','evpn'];return ['switch','routing']}

function chapterCode(d,children){let code=d?.commands||'';let existing=new Set(children.flatMap(u=>(u.config?.code||'').split('\n')).map(s=>s.trim()));if(!existing.size||existing.size===1&&existing.has(''))return code;let extra=code.split('\n').filter(s=>s.trim()&&!existing.has(s.trim())&&!/^(system-view|quit|return)$/.test(s.trim()));return extra.every(s=>/^display /.test(s.trim()))?extra.join('\n'):code}
function lessonPage(id){let x=content.find(a=>a.id===id);if(!x)return heading('未找到知识点','请返回考纲目录选择章节。')+'<a class="secondary" href="#/">返回目录</a>';let d=lessons[x.title],children=units.filter(u=>u.parent===id),parts=subskills.filter(s=>s.parent===id),ordered=orderedChapters(),i=ordered.findIndex(c=>c.id===id),diagram=diagrams[id],stage=curriculum.find(s=>s.chapters.includes(id));let refs=[...new Map([...children.flatMap(u=>u.sources||[]),...sources.filter(s=>getSourceIDs(x).includes(s.id))].map(s=>[s.url,s])).values()];
return `<a class="back" href="#/map/${x.group}">← ${esc(info[x.group][0])} / ${esc(x.category)}</a><div class="lesson-layout"><article class="lesson"><div class="mark-row"><span class="eyebrow">${x.id}</span>${badges(x)}<div class="read-tools"><button id="font-less" aria-label="缩小正文字号">A−</button><button id="font-more" aria-label="放大正文字号">A＋</button><button id="print-chapter">打印</button></div></div><p class="reading-position">${stage?esc(stage.title):''} · 第 ${i+1} / ${ordered.length} 章</p><h1>${esc(x.title)}</h1><section class="chapter-intro"><h2>从一个问题开始</h2><p>${esc(x.intro)}</p><p><strong>读完本章：</strong>${esc(x.outcome)}</p></section><details class="syllabus-detail"><summary>查看原考纲要求</summary><div class="original"><b>考纲要求</b>${esc(x.detail)}</div></details>${x.readingNote?`<p class="reading-note">${esc(x.readingNote)}</p>`:''}${parts.length?`<div class="chapter-outline"><h2>本章知识点</h2><div class="outline-items">${[...parts].sort((a,b)=>{let ai=children.findIndex(u=>u.id===a.id),bi=children.findIndex(u=>u.id===b.id);return (ai<0?999:ai)-(bi<0?999:bi)}).map(s=>children.some(u=>u.id===s.id)?`<a href="#${s.id}" data-scroll="${s.id}">${esc(s.term)} ↓</a>`:`<span>${esc(s.term)}</span>`).join('')}</div></div>`:''}${x.prerequisites.length?`<p class="prerequisites">建议先阅读：${x.prerequisites.map(p=>{let a=content.find(c=>c.id===p);return a?`<a href="#/lesson/${p}">${esc(a.title)}</a>`:''}).join(' · ')}</p>`:''}${children.map(u=>unitSection(u,x)).join('')}<section id="principle"><h2>把本章串起来</h2>${paragraphs(x.explanation)}${d?`<h3>${esc(d.heading)}</h3>${paragraphs(d.deep)}`:''}</section>${chapterCode(d,children)?`<section id="config"><h2>章节配置与查询</h2>${codeHTML(chapterCode(d,children),d.version)}</section>`:''}${d?.fault?`<section id="boundaries"><h2>关键边界与易错点</h2>${paragraphs(d.fault)}</section>`:''}${diagram?`<details class="inline-diagram" id="diagram"><summary>原理演示：${diagram[1]}</summary><div id="diagram-content"></div></details>`:''}${refs.length?`<section id="references"><h2>参考资料</h2>${referenceHTML(refs)}</section>`:`<p class="lab-note">相关技术文档可在<a href="#/sources">参考资料</a>中查阅。</p>`}<p class="lab-note">配置以所注产品版本为参考，尚未在赛事设备上验证。</p><div class="chapter-pagination">${ordered[i-1]?`<a href="#/lesson/${ordered[i-1].id}">← 上一章：${esc(ordered[i-1].title)}</a>`:'<a href="#/learn">← 学习顺序</a>'}${ordered[i+1]?`<a href="#/lesson/${ordered[i+1].id}">下一章：${esc(ordered[i+1].title)} →</a>`:'<a href="#/learn">返回学习顺序 →</a>'}</div></article><aside class="toc"><p>本章目录</p>${children.map(u=>`<a href="#${u.id}" data-scroll="${u.id}">${esc(u.term)}</a>`).join('')}<a href="#principle" data-scroll="principle">把本章串起来</a>${chapterCode(d,children)?'<a href="#config" data-scroll="config">章节配置与查询</a>':''}${d?.fault?'<a href="#boundaries" data-scroll="boundaries">关键边界与易错点</a>':''}${diagram?'<a href="#diagram" data-scroll="diagram">原理演示</a>':''}${refs.length?'<a href="#references" data-scroll="references">参考资料</a>':''}</aside></div>`}
function sourcePage(){return heading('考纲与参考资料','查阅原始考纲，以及相关产品文档与协议标准。')+`<section class="panel"><h2>考纲范围</h2><p class="sub">保留数通、DCN、安全、WLAN四个方向的94条考纲条目。省资格赛与省赛按原考纲勾选标注，未勾选项仍保留。</p><div class="actions"><a class="secondary" href="assets/syllabus.png" target="_blank">查看原始考纲 ↗</a><a class="secondary" href="handbook.html">阅读离线手册 ↗</a></div></section><div class="section-title"><h2>技术文档与标准</h2></div><section class="panel">${sources.map(s=>`<div class="source"><a href="${safeURL(s.url)}" target="_blank" rel="noopener">${esc(s.title)} ↗</a><p>${esc(s.version)} · ${esc(s.scope)}</p></div>`).join('')}</section>`}
function bind(route,id){if(route==='map'){for(let k of ['stage','depth']){let e=$('#'+k+'-filter');e.value=filters[k];e.onchange=()=>{filters[k]=e.value;renderList()}}$('#map-query').oninput=e=>{filters.query=e.target.value;renderList()};$('#group-tabs').onclick=e=>{let b=e.target.closest('[data-group]');if(!b)return;filters.group=b.dataset.group;$('#group-tabs').querySelectorAll('button').forEach(z=>z.classList.toggle('active',z===b));renderList()};renderList()}
if(route==='lesson'&&$('#font-more')){$('#font-more').onclick=()=>{$('#main').classList.remove('small');$('#main').classList.add('wide')};$('#font-less').onclick=()=>{$('#main').classList.remove('wide');$('#main').classList.add('small')};$('#print-chapter').onclick=()=>{loadDiagram(id);window.print()};if($('#diagram'))$('#diagram').ontoggle=()=>{if($('#diagram').open)loadDiagram(id)}}
document.querySelectorAll('[data-scroll]').forEach(a=>a.onclick=e=>{e.preventDefault();let target=document.getElementById(a.dataset.scroll);if(target){if(target.tagName==='DETAILS')target.open=true;target.scrollIntoView({block:'start'})}})}
function loadDiagram(id){let host=$('#diagram-content');if(!host||host.children.length)return;let kind=diagrams[id][0];host.innerHTML=({subnet:subnetHTML,switch:switchHTML,vlan:vlanHTML,route:routeHTML}[kind])();bindDiagram(kind)}
function render(){let raw;try{raw=decodeURIComponent(location.hash.slice(1)||'/').split('?')[0]}catch{raw='/'}let [,r,id]=raw.split('/');if(!r)r='learn';let anchor=null;if(r==='unit'){let u=units.find(u=>u.id===id);if(u){id=u.parent;r='lesson';anchor=u.id}}let route=r==='lesson'?'lesson':r==='sources'?'sources':r==='learn'?'learn':'map';if(route==='map'&&!['map',''].includes(r||''))filters.group='全部';$('#crumb').textContent=route==='lesson'?'知识点讲解':route==='sources'?'考纲与参考资料':route==='learn'?'推荐学习顺序':'考纲知识目录';document.querySelectorAll('[data-nav]').forEach(e=>e.classList.toggle('active',e.dataset.nav===(route==='lesson'?'learn':route)));$('.sidebar').classList.remove('open');$('.menu').setAttribute('aria-expanded','false');$('#main').classList.remove('wide','small');$('#main').innerHTML=route==='lesson'?lessonPage(id):route==='sources'?sourcePage():route==='learn'?learningPage():mapPage(r==='map'?id:null);bind(route,id);if(route==='lesson'&&window.ICTTeaching){window.ICTTeaching.mount($('#main'));if(['ICT-001','ICT-002','ICT-003'].includes(id))window.ICTTeaching.annotate($('.lesson'))}learningSidebar(route==='lesson'?id:null);window.scrollTo(0,0);if(anchor)document.getElementById(anchor)?.scrollIntoView();document.title=(route==='lesson'?(content.find(x=>x.id===id)?.title||'知识点讲解'):$('#crumb').textContent)+' · 网络探索站'}
function search(){let q=$('#global-search').value.trim().toLowerCase();let parents=content.filter(x=>!q||searchable(x).includes(q)).slice(0,q?20:12);let children=q?units.filter(u=>[u.term,u.explain,JSON.stringify(u.walkthrough||{}),u.config?.code||''].join(' ').toLowerCase().includes(q)).slice(0,8):[];$('#search-results').innerHTML=parents.length||children.length?children.map(u=>`<a href="#/unit/${u.id}">${esc(u.term)}<small>${esc(content.find(x=>x.id===u.parent).title)} · 知识点讲解</small></a>`).join('')+parents.map(x=>`<a href="#/lesson/${x.id}">${esc(x.title)}<small>${esc(x.group)} / ${esc(x.category)}</small></a>`).join(''):'<p class="empty">没有匹配结果。</p>'}
$('.search-open').onclick=()=>{$('#search-dialog').showModal();$('#global-search').focus();search()};$('#global-search').oninput=search;$('#search-results').onclick=e=>{if(e.target.closest('a'))$('#search-dialog').close()};$('.nav-close').onclick=()=>{$('.sidebar').classList.remove('open');$('.menu').setAttribute('aria-expanded','false')};$('.menu').onclick=()=>{$('.sidebar').classList.toggle('open');$('.menu').setAttribute('aria-expanded',String($('.sidebar').classList.contains('open')))};document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('.sidebar').classList.remove('open');$('.menu').setAttribute('aria-expanded','false')}if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){e.preventDefault();$('.search-open').click()}});window.addEventListener('hashchange',render);$('.skip').onclick=e=>{e.preventDefault();$('#main').focus();$('#main').scrollIntoView()};
(window.ICT_DATA?Promise.resolve(window.ICT_DATA):Promise.all(['content.json','lessons.json','sources.json','subskills.json','units.json','curriculum.json'].map(p=>fetch(p).then(r=>{if(!r.ok)throw Error('无法加载 '+p);return r.json()})))).then(([c,l,s,sub,u,cur])=>{content=c;lessons=l;sources=s;subskills=sub;units=u||[];curriculum=cur||[];render()}).catch(e=>{$('#main').innerHTML=`<p class="empty">${esc(e.message)}。请使用本地HTTP服务打开。</p>`});
